'use client'

import { useEffect, useMemo, useState } from 'react'
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, BookOpenCheck, CalendarCheck, CalendarDays, Check, ChevronDown, CircleHelp, ClipboardCheck, ClipboardList, CreditCard, FileText, GraduationCap, LayoutDashboard, LogOut, Menu, Moon, MoreHorizontal, Search, Settings, ShieldCheck, Sun, Users, Wallet, X, Megaphone, BookOpen, Plus, Clock3, Download, AlertCircle, SlidersHorizontal, Send, CheckCircle2, FileUp, LockKeyhole } from 'lucide-react'
import { activities, announcements, attendanceRoster, classes, evaluations, feeStatus, payments, roleNames, roleSections, schedule, school, stats, students, type Language, type SchoolRole, type Section } from '@/mocks/school'
import { sectionLabels, translations } from '@/mocks/translations'
import { schoolApi } from '@/lib/api'
import { ConfirmDialog, DataTable, EmptyState, FormStepper, StatCard, StatusBadge } from '@/components/school-ui'
import { StudentRecords } from '@/components/student-records'
import { SchoolStructure } from '@/components/school-structure'
import { AttendanceWorkspace, GradesWorkspace } from '@/components/academic-workflows'
import { BulletinModule, CommunicationModule, FinanceModule, ResourcesModule } from '@/components/school-advanced-sections'

const navIcons: Record<Section, React.ElementType> = { overview: LayoutDashboard, students: Users, classes: GraduationCap, attendance: CalendarCheck, grades: BookOpenCheck, bulletins: FileText, finance: Wallet, communication: Megaphone, resources: BookOpen, documents: ClipboardList, users: ShieldCheck, audit: Activity, settings: Settings }
const roles: SchoolRole[] = ['principal','censor','secretary','accountant','head_teacher','teacher','department_head','parent','student','super_admin']
const currency = new Intl.NumberFormat('fr-FR', { maximumFractionDigits: 0 })
const roleDefaultSection: Partial<Record<SchoolRole, Section>> = { parent: 'overview', student: 'overview' }
type Presence = 'present' | 'absent' | 'late' | 'unmarked'
let activeLanguage: Language = 'fr'

export function SchoolApp() {
  const [role, setRole] = useState<SchoolRole>('principal')
  const [language, setLanguage] = useState<Language>('fr')
  const [dark, setDark] = useState(false)
  const [isOnline, setIsOnline] = useState(false)
  const [active, setActive] = useState<Section>('overview')
  const [mobileMenu, setMobileMenu] = useState(false)
  const [search, setSearch] = useState('')
  const [toast, setToast] = useState('')
  const [dialog, setDialog] = useState<'attendance'|'grade'|'bulletin'|null>(null)
  const [attendance, setAttendance] = useState<Record<string, Presence>>(() => Object.fromEntries(attendanceRoster.map((student) => [student.id, student.presence])))
  const [gradeValues, setGradeValues] = useState<Record<string, string>>(() => Object.fromEntries(evaluations.map((row) => [row.student, row.value])))
  const [page, setPage] = useState(1)
  const [child, setChild] = useState('Kevin Mballa')
  const [newEnrollment, setNewEnrollment] = useState(false)
  const [step, setStep] = useState(0)
  const [provisional, setProvisional] = useState(true)
  const [paymentOpen, setPaymentOpen] = useState(false)
  const [paymentBusy, setPaymentBusy] = useState(false)
  const [announcementOpen, setAnnouncementOpen] = useState(false)
  activeLanguage = language
  useEffect(() => {
    const updateOnlineStatus = () => setIsOnline(navigator.onLine)
    window.addEventListener('online', updateOnlineStatus)
    window.addEventListener('offline', updateOnlineStatus)
    updateOnlineStatus()
    return () => {
      window.removeEventListener('online', updateOnlineStatus)
      window.removeEventListener('offline', updateOnlineStatus)
    }
  }, [])
  const t = translations[language]
  const visibleSections = roleSections[role]
  const isFamily = role === 'parent' || role === 'student'
  const currentLabel = sectionLabels[language][active]
  const searchedStudents = useMemo(() => students.filter((student) => `${student.name} ${student.id} ${student.className} ${student.guardian}`.toLowerCase().includes(search.toLowerCase())), [search])

  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2800) }
  const changeRole = (nextRole: SchoolRole) => { setRole(nextRole); setActive(roleDefaultSection[nextRole] ?? 'overview'); setMobileMenu(false) }
  const exportCsv = () => {
    const data = students.map((s) => `${s.id},${s.name},${s.className},${s.guardian},${s.phone},${s.status}`).join('\n')
    const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([`Matricule,Élève,Classe,Responsable,Téléphone,Statut\n${data}`], { type: 'text/csv;charset=utf-8' })); link.download = 'eleves-campus.csv'; link.click(); URL.revokeObjectURL(link.href)
  }
  const saveAttendance = async () => { await schoolApi.submitAttendance(attendance); setDialog(null); notify(t.attendanceSaved) }
  const saveGrades = async () => { await schoolApi.saveGrades(gradeValues); setDialog(null); notify(t.gradesSaved) }
  const savePayment = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); if (paymentBusy) return; setPaymentBusy(true); try { const data = Object.fromEntries(new FormData(event.currentTarget)); await schoolApi.createPayment(data); notify(t.paymentRecorded); setPaymentOpen(false); event.currentTarget.reset() } catch { notify(t.errorGeneric) } finally { setPaymentBusy(false) } }

  const renderDashboard = () => {
    if (role === 'parent') return <ParentDashboard t={t} child={child} setChild={setChild} notify={notify}/>
    if (role === 'student') return <StudentDashboard t={t} notify={notify}/>
    if (role === 'teacher' || role === 'head_teacher' || role === 'department_head') return <TeacherDashboard t={t} notify={notify} setActive={setActive}/>
    if (role === 'secretary') return <SecretaryDashboard t={t} setActive={setActive}/>
    if (role === 'accountant') return <AccountantDashboard t={t} setActive={setActive}/>
    return <ManagementDashboard t={t} setActive={setActive} role={role}/>
  }

  const renderSection = () => {
    if (active === 'overview') return renderDashboard()
    if (active === 'students') return <StudentRecords t={t} language={language} role={role} search={search} setSearch={setSearch} notify={notify}/>
    if (active === 'classes') return <SchoolStructure t={t} role={role} language={language} notify={notify}/>
    if (active === 'attendance') return <AttendanceWorkspace language={language} role={role}/>
    if (active === 'grades') return <GradesWorkspace language={language} role={role}/>
    if (active === 'finance') return <FinanceModule role={role} language={language} notify={notify} onPayment={()=>setPaymentOpen(true)}/>
    if (active === 'communication') return <CommunicationModule role={role} language={language} notify={notify} onNewAnnouncement={()=>setAnnouncementOpen(true)}/>
    if (active === 'resources') return <ResourcesModule role={role} language={language} notify={notify}/>
    if (active === 'bulletins') return <BulletinModule role={role} language={language} notify={notify} child={child}/>
    if (active === 'documents') return <DocumentsSection t={t} notify={notify}/>
    if (active === 'users') return <UsersSection t={t}/>
    if (active === 'audit') return <AuditSection t={t}/>
    if (active === 'settings') return <SettingsSection t={t} notify={notify}/>
    return <EmptyState title={t.noData} hint={t.noResultsHint}/>
  }

  const nav = (mobile = false) => <nav className={mobile ? 'side-nav' : 'side-nav'} aria-label={t.menu}>{visibleSections.map((key) => { const Icon = navIcons[key]; return <button key={key} onClick={() => { setActive(key); setMobileMenu(false) }} className={`nav-item ${active === key ? 'selected' : ''}`} aria-current={active === key ? 'page' : undefined}><Icon size={18}/><span>{sectionLabels[language][key]}</span>{key === 'grades' && !isFamily && <span className="nav-count">18</span>}</button> })}</nav>

  return <div className={dark ? 'dark' : ''}>
    <div className="app-shell school-app min-h-screen bg-[#f5f7fa] text-[#202a38] dark:bg-[#111a25] dark:text-slate-100">
      <aside className="sidebar hidden lg:flex">
        <div className="brand-row"><div className="brand-mark"><GraduationCap size={22}/></div><span>{t.appName}<small>GESTION SCOLAIRE</small></span></div>
        <div className="school-switch"><div className="school-emblem">CH</div><div className="min-w-0"><b>{school.name}</b><small>{school.location}</small></div><ChevronDown size={15}/></div>
        <div className="nav-caption">{t.menu.toUpperCase()}</div>{nav()}
        <div className="sidebar-bottom"><div className="academic-card"><div className="academic-icon"><CalendarDays size={16}/></div><div><small>{t.academicYear}</small><b>{school.year}</b></div><ChevronDown size={14}/></div><div className="sidebar-user"><div className="avatar avatar-navy">MN</div><div><b>Marie Ngo Meka</b><small>{roleNames[role][language]}</small></div><MoreHorizontal size={18}/></div></div>
      </aside>
      {mobileMenu && <div className="mobile-overlay lg:hidden" onClick={()=>setMobileMenu(false)}><aside className="mobile-drawer" onClick={(event)=>event.stopPropagation()}><div className="drawer-head"><div className="brand-mark"><GraduationCap size={21}/></div><b>{t.appName}</b><button aria-label="Fermer le menu" onClick={()=>setMobileMenu(false)}><X size={20}/></button></div>{nav(true)}<button className="nav-item" onClick={()=>{setActive('settings');setMobileMenu(false)}}><Settings size={18}/><span>{sectionLabels[language].settings}</span></button></aside></div>}
      <div className="main-column">
        <header className="topbar"><div className="topbar-left"><button className="icon-button lg:hidden" onClick={()=>setMobileMenu(true)} aria-label="Ouvrir le menu"><Menu size={20}/></button><div className="breadcrumb"><span>{school.name}</span><span className="crumb-divider">/</span><b>{currentLabel}</b></div></div>
          <div className="topbar-actions"><label className="search-box"><Search size={16}/><input aria-label={t.search} placeholder={t.search} value={search} onChange={(event)=>setSearch(event.target.value)}/><kbd>⌘ K</kbd></label><button className="icon-button notification-button" aria-label={t.notifications} onClick={()=>setActive('communication')}><Bell size={19}/><i/></button><button className="icon-button" aria-label={t.theme} onClick={()=>setDark(!dark)}>{dark?<Sun size={18}/>:<Moon size={18}/>}</button><button className="language-button" onClick={()=>setLanguage(language==='fr'?'en':'fr')} aria-label={`${t.language}: ${language.toUpperCase()}`}>{language.toUpperCase()}<ChevronDown size={13}/></button><label className="top-role-select"><span className="sr-only">{t.currentRole}</span><select aria-label={t.currentRole} value={role} onChange={(event)=>changeRole(event.target.value as SchoolRole)}>{roles.map((item)=><option key={item} value={item}>{roleNames[item][language]}</option>)}</select></label><button className="profile-button" onClick={()=>notify(`${roleNames[role][language]} · Marie Ngo Meka`)}><div className="avatar avatar-navy">MN</div><span><b>{role==='parent'?'M. Jean Mballa':role==='student'?'Kevin Mballa':'Marie Ngo Meka'}</b><small>{roleNames[role][language]}</small></span><ChevronDown size={14}/></button></div>
        </header>
        <main className="dashboard school-dashboard"><div className="mobile-school-name lg:hidden"><div className="school-emblem">CH</div><div><b>{school.name}</b><small>{school.year}</small></div></div>
          <div className="welcome-row"><div><div className="eyebrow"><span className="live-dot"/> {language==='fr'?'MARDI 18 NOVEMBRE 2025':'TUESDAY, NOVEMBER 18, 2025'} <span className="eyebrow-divider">·</span> {school.year}</div><h1>{active === 'overview' ? t.welcome : currentLabel}</h1><p>{active === 'overview' ? t.welcomeSub : sectionDescription(active, language)}</p></div><div className="role-select-wrap"><label htmlFor="active-role">{t.role}</label><div className="role-select"><ShieldCheck size={16}/><select id="active-role" value={role} onChange={(event)=>changeRole(event.target.value as SchoolRole)}>{roles.map((item)=><option key={item} value={item}>{roleNames[item][language]}</option>)}</select><ChevronDown size={14}/></div></div></div>
          <div className="freshness-banner"><span><CheckCircle2 size={14}/>{t.stale}</span><span className="freshness-right"><span className="live-dot"/>{isOnline ? (language === 'fr' ? 'En ligne' : 'Online') : t.offline}</span></div>
          {renderSection()}
          <footer className="page-footer"><span>© 2025 Campus · {school.name}</span><span><button onClick={()=>notify('Secrétariat : +237 222 31 45 67')}>{t.help}</button><i/> {language==='fr'?'Données de démonstration':'Demo data'}</span></footer>
        </main>
      </div>
      <nav className="bottom-nav lg:hidden" aria-label="Navigation mobile">{visibleSections.slice(0,4).map((key)=>{const Icon=navIcons[key];return <button key={key} className={active===key?'active':''} onClick={()=>setActive(key)}><Icon size={19}/><span>{sectionLabels[language][key]}</span></button>})}<button onClick={()=>setMobileMenu(true)}><Menu size={19}/><span>{t.more}</span></button></nav>
      {dialog && <ConfirmDialog title={t.confirmAction} message={dialog==='attendance'?t.attendanceSubtitle:dialog==='grade'?t.gradesSubtitle:t.bulletinNote} confirmLabel={t.confirm} cancelLabel={t.cancel} onCancel={()=>setDialog(null)} onConfirm={()=>dialog==='attendance'?void saveAttendance():dialog==='grade'?void saveGrades():(setDialog(null),notify(t.saved))}/>}
      {paymentOpen && <div className="dialog-backdrop"><section className="form-dialog" role="dialog" aria-modal="true" aria-labelledby="payment-title"><div className="dialog-heading"><div><h2 id="payment-title">{t.manualPayment}</h2><p>{language==='fr'?'Saisir le paiement reçu hors plateforme.':'Record a payment received outside the platform.'}</p></div><button aria-label="Fermer" className="icon-button" onClick={()=>setPaymentOpen(false)}><X size={19}/></button></div><form onSubmit={(event)=>void savePayment(event)}><label>{t.studentName}<select required name="student"><option value="">Choisir un élève</option>{students.map((s)=><option key={s.id}>{s.name}</option>)}</select></label><label>{t.amount}<input required name="amount" type="number" min="1" step="1" inputMode="numeric" placeholder="125000"/></label><label>{t.paymentMethod}<select name="method"><option>{t.cash}</option><option>{t.transfer}</option><option>{t.cheque}</option><option>{t.mobileMoney}</option></select></label><label>{t.status}<select name="status"><option>{t.paymentPending}</option><option>{t.confirmed}</option></select></label><div className="dialog-actions"><button type="button" className="button-secondary" onClick={()=>setPaymentOpen(false)}>{t.cancel}</button><button type="submit" className="button-primary" disabled={paymentBusy}>{paymentBusy?'…':t.recordPayment}</button></div></form></section></div>}
      {newEnrollment && <EnrollmentDialog t={t} step={step} setStep={setStep} provisional={provisional} setProvisional={setProvisional} onClose={()=>setNewEnrollment(false)} notify={notify}/>}
      {announcementOpen && <AnnouncementDialog t={t} onClose={()=>setAnnouncementOpen(false)} notify={notify}/>}
      {toast && <div className="toast-message" role="status"><CheckCircle2 size={17}/>{toast}</div>}
    </div>
  </div>
}

function sectionDescription(section: Section, language: Language) { const fr: Partial<Record<Section,string>> = { students:'Consultez les dossiers, les pré-inscriptions et les affectations.', classes:'Organisez les classes, les filières et les emplois du temps.', attendance:'Suivez les présences et traitez les justificatifs d’absence.', grades:'Saisissez, contrôlez et validez les résultats scolaires.', finance:'Enregistrez les paiements et suivez les soldes dus.', communication:'Diffusez les informations importantes aux familles et aux élèves.', resources:'Consultez les ressources et les devoirs publiés en classe.', bulletins:'Préparez les bulletins et les conseils de classe.', documents:'Générez les documents administratifs de l’établissement.', users:'Gérez les accès avec des permissions par rôle.', audit:'Consultez les actions effectuées sur la plateforme.', settings:'Personnalisez l’établissement et les règles de calcul.' }; const en: Partial<Record<Section,string>> = { students:'Review student files, pre-enrollments and assignments.', classes:'Manage classes, programs and timetables.', attendance:'Track attendance and review absence notes.', grades:'Enter, review and validate school results.', finance:'Record payments and track outstanding balances.', communication:'Share important information with families and students.', resources:'Browse class resources and homework.', bulletins:'Prepare report cards and class councils.', documents:'Generate school administrative documents.', users:'Manage accounts with role-based permissions.', audit:'Review platform actions.', settings:'Customize school details and calculation rules.' }; return (language==='fr'?fr:en)[section] ?? '' }

type Copy = { [Key in keyof typeof translations.fr]: string }
function ManagementDashboard({t,setActive,role}:{t:Copy;setActive:(key:Section)=>void;role:SchoolRole}) {
  const manager = role==='principal'||role==='super_admin'||role==='censor'
  return <>
    <section className="stats-grid" aria-label="Indicateurs de l’établissement"><StatCard label={t.studentsEnrolled} value="1 248" detail={`+4,8 % · 42 ${t.studentsCount}`} tone="navy" icon={Users}/><StatCard label={t.attendanceRate} value="94,2 %" detail={`1 176 ${t.present.toLowerCase()} · aujourd’hui`} tone="teal" icon={CalendarDays}/><StatCard label={t.gradesPending} value="18" detail={`3 classes · ${t.provisional.toLowerCase()}`} tone="amber" icon={BookOpenCheck}/><StatCard label={t.collectionsMonth} value="8,4 M" detail="FCFA · +12,6 %" tone="green" icon={Wallet}/></section>
    <div className="main-grid"><section className="panel"><div className="panel-heading"><div><h2>{t.classesOverview}</h2><p>{languageText(role,'Répartition des effectifs par niveau','Student distribution by grade')}</p></div><button className="text-action" onClick={()=>setActive('classes')}>{t.seeAll}<ArrowRight size={15}/></button></div><div className="class-list">{classes.slice(0,4).map((item)=><div className="class-row" key={item.name}><div className={`class-avatar ${item.color}`}><GraduationCap size={18}/></div><div className="class-main"><div className="class-title"><b>{item.name}</b><span className="level-pill">{item.stream}</span></div><small>{item.teacher}</small></div><div className="class-students"><b>{item.students}</b><small>{t.studentsCount}</small></div><div className="attendance-col"><div className="attendance-meta"><small>{t.attendanceShort}</small><b>{item.attendance}%</b></div><div className="progress-track"><span style={{width:`${item.attendance}%`}}/></div></div></div>)}</div><button className="all-classes" onClick={()=>setActive('classes')}>{languageText(role,'Consulter la liste des classes','Browse all classes')}<ArrowRight size={15}/></button></section><section className="panel activity-panel"><div className="panel-heading"><div><h2>{t.recentActivity}</h2><p>{languageText(role,'Dernières actions sur la plateforme','Latest actions on the platform')}</p></div><button className="icon-button"><MoreHorizontal size={18}/></button></div><div className="activity-list">{activities.map((item,index)=><div className="activity-row" key={item.name}><div className={`activity-icon activity-${item.kind}`}>{index===0?<BookOpenCheck size={16}/>:index===1?<Users size={16}/>:<CreditCard size={16}/>}</div><div className="activity-copy"><b>{item.name}</b><small>{item.detail}</small><span>{item.time}</span></div></div>)}</div><button className="activity-footer" onClick={()=>setActive('audit')}>{languageText(role,'Voir le journal d’activité','View activity log')}<ArrowRight size={15}/></button></section></div>
    <div className="secondary-grid"><section className="panel"><div className="panel-heading"><div><h2>{t.todaySchedule}</h2><p>{t.scheduleSub}</p></div><button className="text-action" onClick={()=>setActive('classes')}>{t.viewTimetable}<ArrowRight size={15}/></button></div><div className="schedule-list">{schedule.map((item,index)=><div className="schedule-row" key={item.time}><div className="schedule-time"><b>{item.time}</b></div><div className={`schedule-color color-${index}`}/><div className="schedule-content"><b>{item.subject}</b><small>{item.className} · {item.room}</small></div><div className="teacher-avatar">{item.teacher.slice(-2)}</div><small className="teacher-name">{item.teacher}</small></div>)}</div></section><section className="panel"><div className="panel-heading"><div><h2>{manager?t.financeOverview:t.classesOverview}</h2><p>{manager?t.financeSub:languageText(role,'Vos classes du jour','Your classes today')}</p></div><button className="icon-button panel-menu"><MoreHorizontal size={19}/></button></div>{manager?<FinanceMini t={t}/>:<div className="role-action-list">{schedule.map((item)=><div key={item.time}><span className="schedule-dot"/><b>{item.time}</b><span>{item.subject} · {item.className}</span><StatusBadge value={languageText(role,'À faire','To do')}/></div>)}</div>}</section></div>
    <div className="quick-actions"><div><span className="quick-icon"><Check size={17}/></span><div><b>{t.quickAccess}</b><small>{languageText(role,'Actions fréquentes pour votre rôle','Shortcuts for your role')}</small></div></div><div className="quick-buttons"><button onClick={()=>setActive('students')}><Users size={16}/>{t.addStudent}<ArrowRight size={14}/></button><button onClick={()=>setActive('finance')}><CreditCard size={16}/>{t.recordPayment}<ArrowRight size={14}/></button><button onClick={()=>setActive('grades')}><BookOpenCheck size={16}/>{t.validateGrades}<ArrowRight size={14}/></button></div></div>
  </>
}
function languageText(_role:SchoolRole,fr:string,en:string) { return activeLanguage === 'fr' ? fr : en }
function FinanceMini({t}:{t:Copy}) { return <><div className="finance-total"><div><small>{t.totalCollected}</small><b>8 420 000 <span>FCFA</span></b></div><span className="finance-growth"><ArrowUpRight size={14}/>12,6%</span></div><div className="fee-bar">{feeStatus.map((item)=><span key={item.label} className={item.color} style={{width:`${item.value}%`}}/>)}</div><div className="fee-legend">{feeStatus.map((item,index)=><div key={item.label}><span className={`legend-dot ${item.color}`}/><small>{index===0?t.paid:index===1?t.partial:t.overdue}</small><b>{item.value}%</b></div>)}</div></> }
function SecretaryDashboard({t,setActive}:{t:Copy;setActive:(key:Section)=>void}) { return <><div className="stats-grid"><StatCard label={t.enrollmentReview} value="24" detail="6 nouvelles aujourd’hui" tone="navy" icon={ClipboardList}/><StatCard label={t.incompleteFiles} value="17" detail="8 pièces à vérifier" tone="amber" icon={FileText}/><StatCard label={t.pendingAssignments} value="5" detail="2 classes proches du seuil" tone="teal" icon={GraduationCap}/><StatCard label={t.studentsEnrolled} value="1 248" detail="Dossiers actifs" tone="green" icon={Users}/></div><div className="panel"><div className="panel-heading"><div><h2>{t.enrollmentReview}</h2><p>Dernières demandes reçues</p></div><button className="button-primary" onClick={()=>setActive('students')}><Plus size={15}/>{t.newEnrollment}</button></div><StudentsMini/></div></> }
function StudentsMini(){return <div className="compact-list">{students.slice(1,5).map((s)=><div key={s.id}><div className="avatar avatar-navy">{s.name.split(' ').map(x=>x[0]).join('')}</div><div><b>{s.name}</b><small>{s.className} · {s.guardian}</small></div><StatusBadge value={s.status}/></div>)}</div>}
function AccountantDashboard({t,setActive}:{t:Copy;setActive:(key:Section)=>void}) { return <><div className="stats-grid"><StatCard label={t.dailyCollected} value="475 000" detail="FCFA · 8 paiements" tone="green" icon={Wallet}/><StatCard label={t.balances} value="12,6 M" detail="FCFA · 342 élèves" tone="navy" icon={CreditCard}/><StatCard label={t.overdueDue} value="86" detail="échéances à relancer" tone="amber" icon={Clock3}/><StatCard label={t.confirmed} value="7" detail="paiements à vérifier" tone="teal" icon={ClipboardCheck}/></div><FinanceSection t={t} role="accountant" onPayment={()=>setActive('finance')} notify={()=>{}}/></> }
function TeacherDashboard({t,notify,setActive}:{t:Copy;notify:(message:string)=>void;setActive:(key:Section)=>void}) { return <><div className="stats-grid"><StatCard label={t.nextClass} value="3e C" detail="Mathématiques · 07:30" tone="navy" icon={CalendarDays}/><StatCard label={t.unmarked} value="2" detail="appels à effectuer" tone="amber" icon={ClipboardCheck}/><StatCard label={t.gradesPending} value="18" detail="notes à saisir" tone="teal" icon={BookOpenCheck}/><StatCard label={t.resourcesTitle} value="3" detail="ressources publiées" tone="green" icon={BookOpen}/></div><div className="panel"><div className="panel-heading"><div><h2>{languageText('teacher','Mes classes du jour','My classes today')}</h2><p>{t.scheduleSub}</p></div><button className="text-action" onClick={()=>setActive('classes')}>{t.viewTimetable}<ArrowRight size={15}/></button></div><div className="teacher-classes">{schedule.map((item,index)=><div key={item.time}><span>{item.time}</span><span className={`schedule-color color-${index}`}/><div><b>{item.subject}</b><small>{item.className} · {item.room}</small></div><StatusBadge value={index===0?t.unmarked:t.present}/><button className="button-secondary" onClick={()=>setActive('attendance')}>{languageText('teacher','Faire l’appel','Attendance')}</button><button className="button-secondary" onClick={()=>setActive('grades')}>{languageText('teacher','Saisir les notes','Enter grades')}</button></div>)}</div></div></> }
function ParentDashboard({t,child,setChild,notify}:{t:Copy;child:string;setChild:(value:string)=>void;notify:(message:string)=>void}) { return <><div className="parent-child-select"><label htmlFor="child-picker">{t.parentChild}</label><select id="child-picker" value={child} onChange={(e)=>setChild(e.target.value)}><option>Kevin Mballa</option><option>Carine Mballa</option></select></div><div className="stats-grid"><StatCard label={t.absences} value="2" detail="1 absence à justifier" tone="amber" icon={CalendarCheck}/><StatCard label={t.latestGrades} value="14,5/20" detail="Moyenne du trimestre" tone="teal" icon={BookOpenCheck}/><StatCard label={t.upcomingDue} value="75 000" detail="FCFA · 05/12/2025" tone="navy" icon={Wallet}/><StatCard label={sectionLabels[activeLanguage].communication} value="2" detail="annonces non lues" tone="green" icon={Megaphone}/></div><div className="main-grid"><section className="panel"><div className="panel-heading"><div><h2>{languageText('parent','Dernières notes','Recent grades')}</h2><p>Kevin Mballa · 3e C</p></div></div><div className="role-action-list"><div><span className="schedule-dot"/><b>Mathématiques</b><span>Composition 1</span><strong>15/20</strong><StatusBadge value={t.provisional}/></div><div><span className="schedule-dot teal-dot"/><b>Français</b><span>Interrogation 2</span><strong>16/20</strong><StatusBadge value={t.validated}/></div></div></section><section className="panel"><div className="panel-heading"><div><h2>{t.announcementsTitle}</h2><p>{school.name}</p></div></div>{announcements.slice(0,2).map((item)=><div className="notice-row" key={item.title}><b>{item.title}</b><small>{item.date} · {item.audience}</small><p>{item.body}</p></div>)}<button className="button-secondary" onClick={()=>notify('Secrétariat : +237 222 31 45 67')}>{languageText('parent','Contacter le secrétariat','Contact the school office')}</button></section></div><section className="panel"><div className="panel-heading"><div><h2>{t.todaySchedule}</h2><p>{t.stale}</p></div></div><div className="schedule-list">{schedule.map((item,i)=><div className="schedule-row" key={item.time}><div className="schedule-time"><b>{item.time}</b></div><div className={`schedule-color color-${i}`}/><div className="schedule-content"><b>{item.subject}</b><small>{item.className} · {item.room}</small></div></div>)}</div></section></> }
function StudentDashboard({t,notify}:{t:Copy;notify:(message:string)=>void}) { return <><div className="stats-grid"><StatCard label={t.latestGrades} value="14,5/20" detail="Moyenne du trimestre" tone="teal" icon={BookOpenCheck}/><StatCard label={t.absences} value="2" detail="sur ce trimestre" tone="amber" icon={CalendarCheck}/><StatCard label={t.homework} value="4" detail="à consulter" tone="navy" icon={ClipboardList}/><StatCard label={t.resourcesTitle} value="8" detail="fiches disponibles" tone="green" icon={BookOpen}/></div><div className="main-grid"><section className="panel"><div className="panel-heading"><div><h2>{t.todaySchedule}</h2><p>Kevin Mballa · 3e C</p></div></div><div className="schedule-list">{schedule.map((item,i)=><div className="schedule-row" key={item.time}><div className="schedule-time"><b>{item.time}</b></div><div className={`schedule-color color-${i}`}/><div className="schedule-content"><b>{item.subject}</b><small>{item.className} · {item.room}</small></div></div>)}</div></section><section className="panel"><div className="panel-heading"><div><h2>{t.homework}</h2><p>{t.resourcesTitle}</p></div></div><div className="resource-list">{['Exercices sur les fonctions · À rendre 20/11','Lecture : L’Enfant noir · Français','Fiche de révision · Physique'].map((item)=><div key={item}><FileText size={18}/><span>{item}</span><button aria-label={t.download} onClick={()=>notify(t.download)}><Download size={16}/></button></div>)}</div></section></div><section className="panel"><div className="panel-heading"><div><h2>{t.latestGrades}</h2><p>Trimestre 1 · 2025–2026</p></div></div><div className="role-action-list"><div><span className="schedule-dot"/><b>Mathématiques</b><span>Composition 1</span><strong>15/20</strong><StatusBadge value={t.provisional}/></div><div><span className="schedule-dot teal-dot"/><b>Français</b><span>Interrogation 2</span><strong>16/20</strong><StatusBadge value={t.validated}/></div></div></section></> }

function StudentsSection({t,language,role,onNew,onExport,search,setSearch,rows,page,setPage,notify}:{t:Copy;language:Language;role:SchoolRole;onNew:()=>void;onExport:()=>void;search:string;setSearch:(value:string)=>void;rows:typeof students;page:number;setPage:(value:number)=>void;notify:(message:string)=>void}) {
  const columns = [
    { key:'id' as const, label:t.matricule, render:(row:typeof students[number])=><b className="mono-id">{row.id}</b> },
    { key:'name' as const, label:t.studentName, render:(row:typeof students[number])=><span className="student-cell"><span className="avatar avatar-navy">{row.name.split(' ').map(x=>x[0]).join('')}</span><b>{row.name}</b></span> },
    { key:'className' as const, label:t.classLabel }, { key:'guardian' as const, label:t.guardian },
    { key:'status' as const, label:t.status, render:(row:typeof students[number])=><StatusBadge value={row.status}/> },
    { key:'fees' as const, label:t.feesStatus, render:(row:typeof students[number])=><StatusBadge value={row.fees}/> },
  ]
  return <><div className="stats-grid compact-stats"><StatCard label={t.studentsEnrolled} value="1 248" detail="+42 ce trimestre" tone="navy" icon={Users}/><StatCard label={t.enrollmentReview} value="24" detail="Nécessite une vérification" tone="amber" icon={FileUp}/><StatCard label={t.incompleteFiles} value="17" detail="Documents manquants" tone="teal" icon={FileText}/><StatCard label={t.pendingAssignments} value="5" detail="Demandes en cours" tone="green" icon={GraduationCap}/></div><section className="panel"><div className="panel-heading"><div><h2>{t.studentList}</h2><p>{language==='fr'?'Tous les dossiers de l’année scolaire active':'All student files for the current school year'}</p></div><div className="table-actions"><button className="button-secondary" onClick={()=>notify('Aperçu Excel prêt à être importé.')}><FileUp size={15}/>{t.importExcel}</button>{role==='secretary'&&<button className="button-primary" onClick={onNew}><Plus size={15}/>{t.newEnrollment}</button>}</div></div><div className="filter-row"><label className="table-search"><Search size={16}/><input aria-label={t.search} placeholder={t.search} value={search} onChange={(event)=>setSearch(event.target.value)}/></label><label><SlidersHorizontal size={15}/><select aria-label={t.classLabel}><option value="">{t.classLabel} · {t.filters}</option>{classes.map((c)=><option key={c.name}>{c.name}</option>)}</select></label><label><select aria-label={t.stream}><option value="">{t.stream}</option><option>Général</option><option>Électrotechnique</option><option>Comptabilité</option></select></label><label><select aria-label={t.status}><option value="">{t.status}</option><option>Actif</option><option>Pré-inscription</option><option>Dossier incomplet</option></select></label><button className="button-secondary" onClick={onExport}><Download size={15}/>{t.export}</button></div><div className="table-scroll"><table><thead><tr>{columns.map((c)=><th key={c.key}>{c.label}</th>)}<th>{t.actions}</th></tr></thead><tbody>{rows.map((row)=><tr key={row.id}>{columns.map((c)=><td key={c.key}>{c.render?c.render(row):row[c.key]}</td>)}<td><button className="table-more" aria-label={`${t.seeDetails} ${row.name}`} onClick={()=>notify(`${row.name} · ${row.id}`)}><MoreHorizontal size={17}/></button></td></tr>)}</tbody></table>{rows.length===0&&<EmptyState title={t.noResults} hint={t.noResultsHint}/>}</div><div className="table-pagination"><small>Affichage de {(page-1)*5+1} à {Math.min(page*5,students.length)} sur {students.length} résultats</small><div><button aria-label={t.previous} disabled={page===1} onClick={()=>setPage(Math.max(1,page-1))}>‹</button><button className="page-number" aria-current="page">{page}</button><button aria-label={t.next} disabled={page*5>=students.length} onClick={()=>setPage(page+1)}>›</button></div></div></section></>
}
function StructureSection({t,role,notify}:{t:Copy;role:SchoolRole;notify:(message:string)=>void}) { return <><div className="stats-grid compact-stats"><StatCard label={t.classLabel} value="32" detail="Général et technique" tone="navy" icon={GraduationCap}/><StatCard label={t.studentsEnrolled} value="1 248" detail="Effectifs affectés" tone="teal" icon={Users}/><StatCard label={t.pendingAssignments} value="5" detail="Demandes de dérogation" tone="amber" icon={AlertCircle}/><StatCard label={t.assignments} value="84" detail="Enseignants affectés" tone="green" icon={ShieldCheck}/></div><section className="panel"><div className="panel-heading"><div><h2>{t.structureTitle}</h2><p>{languageText(role,'Capacité, filière et professeur principal','Capacity, program and head teacher')}</p></div><button className="button-primary" onClick={()=>notify(t.exceptionSent)}><Plus size={15}/>{t.requestException}</button></div><div className="class-cards">{classes.map((item)=><article className="class-detail-card" key={item.name}><div className="class-card-top"><span className={`class-avatar ${item.color}`}><GraduationCap size={18}/></span><StatusBadge value={item.students>=item.capacity?'Complet':t.present}/></div><h3>{item.name}</h3><p>{item.stream}</p><div className="capacity-row"><span>{item.students} / {item.capacity} {t.studentsCount}</span><b>{Math.round(item.students/item.capacity*100)}%</b></div><div className="progress-track"><span style={{width:`${item.students/item.capacity*100}%`}}/></div><small>{t.teacher} · {item.teacher}</small></article>)}</div></section><section className="panel"><div className="panel-heading"><div><h2>{languageText(role,'Emploi du temps hebdomadaire','Weekly timetable')}</h2><p>3e C · Semaine du 17 novembre 2025</p></div><button className="button-secondary" onClick={()=>notify('Emploi du temps exporté.')}>{t.export}</button></div><div className="schedule-list">{schedule.map((item,i)=><div className="schedule-row" key={item.time}><div className="schedule-time"><b>{item.time}</b></div><div className={`schedule-color color-${i}`}/><div className="schedule-content"><b>{item.subject}</b><small>{item.className} · {item.room} · {item.teacher}</small></div><span className="level-pill">Lundi</span></div>)}</div></section></> }
function AttendanceSection({t,attendance,setAttendance,onSave}:{t:Copy;attendance:Record<string,Presence>;setAttendance:React.Dispatch<React.SetStateAction<Record<string,Presence>>>;onSave:()=>void}) { const count=Object.values(attendance).filter(v=>v!=='unmarked').length; return <><div className="attendance-toolbar panel"><div><label>{t.classLabel}<select><option>3e C</option>{classes.map(c=><option key={c.name}>{c.name}</option>)}</select></label><label>{t.period}<input type="date" defaultValue="2025-11-18"/></label></div><div className="attendance-summary"><b>{count} / {attendanceRoster.length}</b><small>élèves pointés</small><span className={count===attendanceRoster.length?'complete-dot':'pending-dot'}>{count===attendanceRoster.length?t.present:t.unmarked}</span></div></div><div className="panel"><div className="panel-heading"><div><h2>{t.attendanceTitle} · 3e C</h2><p>{t.attendanceSubtitle}</p></div><button className="button-secondary" onClick={()=>setAttendance(Object.fromEntries(attendanceRoster.map((s)=>[s.id,'present'])))}><Check size={15}/>{t.markAllPresent}</button></div><div className="attendance-list">{attendanceRoster.map((student)=><div className="attendance-student" key={student.id}><span className="avatar avatar-navy">{student.name.split(' ').map(x=>x[0]).join('')}</span><div className="attendance-student-name"><b>{student.name}</b><small>{student.id}</small></div><div className="attendance-options" role="group" aria-label={`${student.name} · ${t.attendanceTitle}`}>{(['present','absent','late'] as const).map((state)=><button key={state} aria-pressed={attendance[student.id]===state} className={`${attendance[student.id]===state?'chosen':''} ${state}`} onClick={()=>setAttendance((current)=>({...current,[student.id]:state}))}>{state==='present'?t.present:state==='absent'?t.absent:t.late}</button>)}</div>{attendance[student.id]==='unmarked'&&<StatusBadge value={t.unmarked}/>}</div>)}</div><div className="panel-footer"><span>{t.unmarked}: {Object.values(attendance).filter(v=>v==='unmarked').length}</span><button className="button-primary" onClick={onSave}><Check size={15}/>{t.submitAttendance}</button></div></div></> }
function ParentAttendance({t,notify}:{t:Copy;notify:(message:string)=>void}) { return <div className="main-grid"><section className="panel"><div className="panel-heading"><div><h2>{t.absences} · Kevin Mballa</h2><p>3e C · Trimestre 1</p></div><StatusBadge value="2 absences"/></div><div className="role-action-list"><div><span className="schedule-dot"/><b>06/11/2025</b><span>Retard · 08:12</span><StatusBadge value="À justifier"/></div><div><span className="schedule-dot"/><b>12/11/2025</b><span>Absence · Journée complète</span><StatusBadge value="À justifier"/></div></div></section><section className="panel"><div className="panel-heading"><div><h2>{t.justifyAbsence}</h2><p>Déposez un justificatif pour votre enfant.</p></div></div><form className="inline-form" onSubmit={(e)=>{e.preventDefault();notify('Justificatif déposé.')}}><label>{t.reason}<textarea required rows={3} placeholder="Indiquez le motif de l’absence"/></label><label>{t.period}<input type="date" required/></label><label>{t.attachment}<input type="file" accept="image/*,.pdf"/></label><button className="button-primary" type="submit"><Send size={15}/>{t.submit}</button></form></section></div> }
function GradesSection({t,values,setValues,onSave,role}:{t:Copy;values:Record<string,string>;setValues:React.Dispatch<React.SetStateAction<Record<string,string>>>;onSave:()=>void;role:SchoolRole}) { return <><div className="grade-toolbar panel"><div><label>{t.classLabel}<select><option>3e C</option>{classes.map(c=><option key={c.name}>{c.name}</option>)}</select></label><label>{languageText(role,'Matière','Subject')}<select><option>Mathématiques</option><option>Français</option><option>Physique</option></select></label><label>{languageText(role,'Évaluation','Assessment')}<select><option>Composition 1</option><option>Interrogation 2</option></select></label></div><button className="button-secondary"><Plus size={15}/>{languageText(role,'Créer une évaluation','Create assessment')}</button></div><section className="panel"><div className="panel-heading"><div><h2>{t.gradesTitle}</h2><p>{t.gradesSubtitle}</p></div><StatusBadge value={t.provisional}/></div><div className="table-scroll"><table><thead><tr><th>{t.studentName}</th><th>{t.matricule}</th><th>{languageText(role,'Note /20','Grade /20')}</th><th>{t.status}</th></tr></thead><tbody>{evaluations.map((row)=>{const value=values[row.student]??row.value;return <tr key={row.student}><td><b>{row.student}</b></td><td className="mono-id">{students.find(s=>s.name===row.student)?.id}</td><td><div className="grade-input"><input aria-label={`${row.student} · ${languageText(role,'note','grade')}`} value={value} onChange={(e)=>setValues((curr)=>({...curr,[row.student]:e.target.value}))} placeholder="15"/><select aria-label={`${row.student} · ${t.status}`} value={['Absent','Dispensé','Non noté'].includes(value)?value:'Note'} onChange={(e)=>setValues((curr)=>({...curr,[row.student]:e.target.value==='Note'?'':e.target.value}))}><option>Note</option><option>Absent</option><option>Dispensé</option><option>Non noté</option></select></div></td><td><StatusBadge value={row.status}/></td></tr>})}</tbody></table></div><div className="panel-footer"><span><ShieldCheck size={16}/>Les notes non validées restent provisoires.</span><div><button className="button-secondary" onClick={onSave}>{t.saveDraft}</button>{['censor','principal','super_admin'].includes(role)?<button className="button-primary" onClick={onSave}>{t.validate}</button>:null}</div></div></section><section className="panel info-panel"><LockKeyhole size={18}/><div><b>{languageText(role,'Validation et verrouillage','Validation & lock')}</b><p>{languageText(role,'Une validation globale vérifie les notes manquantes par classe et matière. Les corrections post-validation nécessitent une autorisation du censeur.','Global validation checks for missing grades by class and subject. Corrections after validation require censor approval.')}</p></div></section></> }

function FinanceSection({t,role,onPayment,notify}:{t:Copy;role:SchoolRole;onPayment:()=>void;notify:(message:string)=>void}) { return <><div className="stats-grid compact-stats"><StatCard label={t.dailyCollected} value="475 000" detail="FCFA · 8 paiements" tone="green" icon={Wallet}/><StatCard label={t.balances} value="12 640 000" detail="FCFA à recouvrer" tone="navy" icon={CreditCard}/><StatCard label={t.overdueDue} value="86" detail="échéances à relancer" tone="amber" icon={Clock3}/><StatCard label={t.confirmed} value="7" detail="à vérifier" tone="teal" icon={CheckCircle2}/></div><section className="panel"><div className="panel-heading"><div><h2>{t.financeTitle}</h2><p>{t.financeSub}</p></div>{role==='accountant'&&<button className="button-primary" onClick={onPayment}><Plus size={15}/>{t.manualPayment}</button>}</div><div className="finance-overview-grid"><div className="finance-highlight"><small>{t.totalCollected}</small><strong>8 420 000 <span>FCFA</span></strong><div className="fee-bar">{feeStatus.map(item=><span className={item.color} key={item.label} style={{width:`${item.value}%`}}/>)}</div><div className="fee-legend">{feeStatus.map((item,index)=><div key={item.label}><span className={`legend-dot ${item.color}`}/><small>{index===0?t.paid:index===1?t.partial:t.overdue}</small><b>{item.value}%</b></div>)}</div></div><div className="payment-method-summary"><b>{languageText(role,'Frais par filière','Fees by program')}</b><div><span>Premier cycle général</span><b>180 000 FCFA</b></div><div><span>Second cycle général</span><b>225 000 FCFA</b></div><div><span>Technique · F3</span><b>310 000 FCFA</b></div><button className="text-action" onClick={()=>notify(languageText(role,'Échéancier standard affiché','Standard schedule displayed'))}>{languageText(role,'Voir les échéanciers','View schedules')}<ArrowRight size={15}/></button></div></div></section><section className="panel"><div className="panel-heading"><div><h2>{languageText(role,'Derniers paiements','Recent payments')}</h2><p>{languageText(role,'Reçus enregistrés · aucun paiement en ligne','Recorded receipts · no online payments')}</p></div><button className="button-secondary" onClick={()=>notify(t.export)}><Download size={15}/>{t.export}</button></div><div className="table-scroll"><table><thead><tr><th>{t.receipt}</th><th>{t.studentName}</th><th>{languageText(role,'Motif','Reason')}</th><th>{t.amount}</th><th>{t.paymentMethod}</th><th>{t.status}</th><th>{t.actions}</th></tr></thead><tbody>{payments.map((p)=><tr key={p.receipt}><td><b className="mono-id">{p.receipt}</b></td><td>{p.student}</td><td>{p.reason}</td><td>{currency.format(p.amount)} FCFA</td><td>{p.method}</td><td><StatusBadge value={p.status=== 'Confirmé'?t.confirmed:t.paymentPending}/></td><td><button className="table-more" aria-label={`${t.receipt} ${p.receipt}`} onClick={()=>notify(`${t.receipt} ${p.receipt} · QR de vérification privé`)}><MoreHorizontal size={17}/></button></td></tr>)}</tbody></table></div><div className="panel-footer"><span><ShieldCheck size={16}/>{languageText(role,'Le QR de reçu ne divulgue aucun détail financier.','Receipt QR codes expose no financial details.')}</span><button className="button-secondary" onClick={()=>notify(languageText(role,'Relance par e-mail prête à configurer','Email reminder ready to configure'))}>{languageText(role,'Préparer une relance','Prepare reminder')}</button></div></section></> }
function AnnouncementsSection({t,role,open,setOpen,notify}:{t:Copy;role:SchoolRole;open:boolean;setOpen:(value:boolean)=>void;notify:(message:string)=>void}) { return <><div className="panel"><div className="panel-heading"><div><h2>{t.announcementsTitle}</h2><p>{languageText(role,'Informations officielles diffusées par l’établissement.','Official school updates.')}</p></div>{['principal','super_admin','secretary','censor'].includes(role)&&<button className="button-primary" onClick={()=>setOpen(true)}><Plus size={15}/>{t.publishAnnouncement}</button>}</div><div className="notice-list">{announcements.map((item,index)=><article className={`notice-card ${item.urgent?'urgent':''}`} key={item.title}><div className="notice-icon">{item.urgent?<AlertCircle size={18}/>:<Megaphone size={18}/>}</div><div className="notice-copy"><div className="notice-title"><h3>{item.title}</h3>{item.urgent&&<StatusBadge value={t.urgent}/>}</div><small>{item.audience} · {item.date}</small><p>{item.body}</p><span>{index===0?'Non lu':'Lu'} · {t.school}</span></div><button className="button-secondary" onClick={()=>notify(languageText(role,'Marquée comme lue','Marked as read'))}>{languageText(role,'Marquer comme lu','Mark as read')}</button></article>)}</div></div><section className="panel contact-panel"><div className="contact-icon"><CircleHelp size={20}/></div><div><b>{languageText(role,'Besoin d’aide ?','Need help?')}</b><p>{languageText(role,'Pour toute question, contactez le secrétariat. La messagerie directe n’est pas disponible.','For assistance, contact the school office. Direct messaging is not available.')}</p></div><a href="tel:+237222314567">+237 222 31 45 67</a></section></> }
function ResourcesSection({t,role,notify}:{t:Copy;role:SchoolRole;notify:(message:string)=>void}) { const resources=[['Fiche de révision — Fonctions','Mathématiques · 3e C','248 Ko'],['Travaux pratiques — Circuits électriques','Électrotechnique · Tle F3','412 Ko'],['Méthode de commentaire composé','Français · 1ère D','196 Ko'],['Exercices de physique — Électricité','Physique · 2nde C','325 Ko']]; return <><section className="panel"><div className="panel-heading"><div><h2>{t.resourcesTitle}</h2><p>{t.readOnly}</p></div>{['teacher','head_teacher','department_head'].includes(role)&&<button className="button-primary" onClick={()=>notify(languageText(role,'Publication bientôt disponible','Publishing coming soon'))}><Plus size={15}/>{languageText(role,'Publier une ressource','Publish a resource')}</button>}</div><div className="resource-list">{resources.map(([title,subject,size])=><div key={title}><span className="resource-file"><FileText size={18}/></span><span className="resource-meta"><b>{title}</b><small>{subject} · {size}</small></span><button className="button-secondary" onClick={()=>notify(`${t.download} · ${title}`)}><Download size={15}/>{t.download}</button></div>)}</div></section><section className="panel info-panel"><BookOpen size={18}/><div><b>{t.readOnly}</b><p>{languageText(role,'Les devoirs sont publiés par les enseignants. Le dépôt de travaux en ligne est désactivé.','Homework is published by teachers. Online work submissions are disabled.')}</p></div></section></> }
function BulletinsSection({t,role,onPublish,notify}:{t:Copy;role:SchoolRole;onPublish:()=>void;notify:(message:string)=>void}) { return <><div className="panel"><div className="panel-heading"><div><h2>{t.bulletinTitle}</h2><p>{t.term} 1 · 2025–2026 · 3e C</p></div><div className="table-actions"><button className="button-secondary" onClick={()=>notify(t.pdfUnavailable)}><Download size={15}/>PDF</button>{['principal','censor','super_admin'].includes(role)&&<button className="button-primary" onClick={onPublish}><Send size={15}/>{t.publishBulletins}</button>}</div></div><div className="bulletin-preview"><div className="bulletin-heading"><span className="school-emblem">CH</span><div><b>{school.name}</b><small>Yaoundé · Année scolaire 2025–2026</small></div><span className="level-pill">Bulletin · Trimestre 1</span></div><h3>{t.bulletinNote} · Kevin Mballa</h3><p>Classe : 3e C · Effectif : 38 · Rang : 7e</p><div className="table-scroll"><table><thead><tr><th>Matière</th><th>Moyenne</th><th>Coeff.</th><th>Moy. pondérée</th><th>Appréciation</th></tr></thead><tbody>{[['Mathématiques','15,0','4','15,0','Bon travail'],['Français','14,5','4','14,5','En progrès'],['Physique','13,0','3','13,0','Assez bien'],['Anglais','16,0','2','16,0','Très bien']].map((r)=><tr key={r[0]}>{r.map(v=><td key={v}>{v}</td>)}</tr>)}</tbody></table></div><div className="bulletin-footer"><span>Moyenne générale <b>14,5 / 20</b></span><span>Mention <b>Bien</b></span><StatusBadge value={t.provisional}/></div><p className="bulletin-appreciation">Appréciation générale : Bon trimestre. Kevin participe avec sérieux. Poursuivre les efforts en physique.</p></div></div><div className="panel council-card"><div className="panel-heading"><div><h2>{languageText(role,'Conseil de classe','Class council')}</h2><p>{languageText(role,'Préparation des décisions et procès-verbal','Prepare decisions and minutes')}</p></div><button className="button-secondary" onClick={()=>notify(t.pdfUnavailable)}><Download size={15}/>PV PDF</button></div><div className="council-row"><b>3e C · Conseil du 20/11/2025</b><StatusBadge value={languageText(role,'En préparation','In preparation')}/><button className="button-primary" onClick={()=>notify(t.saved)}>{t.prepareCouncil}</button></div><p>{languageText(role,'Les familles ne voient que les décisions concernant leur enfant. Le procès-verbal complet reste réservé à la direction.','Families only see decisions concerning their child. Full minutes are restricted to administration.')}</p></div></> }
function DocumentsSection({t,notify}:{t:Copy;notify:(message:string)=>void}) { return <section className="panel"><div className="panel-heading"><div><h2>{t.documentsTitle}</h2><p>{languageText('principal','Documents générés à partir des modèles de l’établissement.','Documents generated from school templates.')}</p></div></div><div className="document-grid">{[[t.certificate,'Pour les démarches administratives'],[t.enrollmentCertificate,'Dossier de pré-inscription'],[t.summons,'Famille · Élève · Classe']].map(([name,description])=><article key={name}><span><FileText size={20}/></span><h3>{name}</h3><p>{description}</p><label>{languageText('principal','Élève','Student')}<select><option>Kevin Mballa · 3e C</option>{students.map(s=><option key={s.id}>{s.name} · {s.className}</option>)}</select></label><button className="button-primary" onClick={()=>notify(t.documentReady)}><Download size={15}/>{t.generateDocument}</button></article>)}</div></section> }
function UsersSection({t}:{t:Copy}) { const roleNamesList=roles.map((role)=>({role:roleNames[role].fr,accounts:role==='teacher'?42:role==='parent'?860:role==='student'?1248:role==='principal'?1:role==='secretary'?4:role==='accountant'?2:role==='censor'?2:role==='head_teacher'?28:role==='department_head'?6:1,rights:roleSections[role].length})); return <><div className="stats-grid compact-stats"><StatCard label={t.usersTitle} value="2 194" detail="Comptes actifs" tone="navy" icon={Users}/><StatCard label={t.currentRole} value="10" detail="Rôles disponibles" tone="teal" icon={ShieldCheck}/><StatCard label={t.auditTitle} value="42" detail="Actions aujourd’hui" tone="amber" icon={Activity}/><StatCard label={t.settingsTitle} value="1" detail="Établissement" tone="green" icon={Settings}/></div><section className="panel"><div className="panel-heading"><div><h2>{t.permissionMatrix}</h2><p>La navigation et les actions sont limitées au rôle actif.</p></div><button className="button-primary"><Plus size={15}/>Ajouter un utilisateur</button></div><div className="table-scroll"><table><thead><tr><th>Rôle</th><th>Comptes</th><th>Modules autorisés</th><th>{t.status}</th></tr></thead><tbody>{roleNamesList.map((r)=><tr key={r.role}><td><b>{r.role}</b></td><td>{r.accounts}</td><td>{r.rights} modules</td><td><StatusBadge value="Actif"/></td></tr>)}</tbody></table></div></section></> }
function AuditSection({t}:{t:Copy}) { const entries=[['Marie Ngo Meka','Validation des notes','Notes · 1ère D','Complétude vérifiée avant validation','18/11/2025 · 09:42'],['Pauline Fokam','Modification du dossier','Élève · CEH-25-00417','Ajout du contact d’urgence','18/11/2025 · 09:18'],['André Tchinda','Enregistrement d’un paiement','Reçu · REC-25-01840','Virement confirmé par la comptabilité','17/11/2025 · 16:32'],['Serge Tchoumi','Saisie de l’appel','Classe · 3e C','Appel du matin enregistré','17/11/2025 · 08:05']]; return <section className="panel"><div className="panel-heading"><div><h2>{t.auditTitle}</h2><p>Traçabilité des actions sensibles · consultation uniquement</p></div><button className="button-secondary"><SlidersHorizontal size={15}/>{t.filters}</button></div><div className="audit-list">{entries.map(([actor,action,target,reason,date])=><article key={`${actor}${date}`}><span className="audit-dot"/><div><b>{action}</b><small>{actor} · {target}</small><p>{t.auditReason} : {reason}</p></div><time>{date}</time></article>)}</div></section> }
function SettingsSection({t,notify}:{t:Copy;notify:(message:string)=>void}) { return <div className="settings-grid"><section className="panel"><div className="panel-heading"><div><h2>{t.settingsTitle}</h2><p>Les couleurs peuvent être personnalisées par établissement.</p></div></div><form className="settings-form" onSubmit={(e)=>{e.preventDefault();notify(t.saved)}}><label>Nom de l’établissement<input defaultValue={school.name}/></label><label>{t.logo}<input type="file" accept="image/*"/></label><label>{t.primaryColor}<div className="color-input"><input type="color" defaultValue="#1f3a5f"/><span>#1F3A5F</span></div></label><label>{t.academicYear}<select defaultValue="2025–2026"><option>2025–2026</option><option>2026–2027</option></select></label><label>{languageText('principal','Règle de calcul de moyenne','Grade calculation rule')}<select><option>Moyenne pondérée par coefficient</option><option>Moyenne simple</option></select></label><button className="button-primary" type="submit"><Check size={15}/>{t.saveSettings}</button></form></section><section className="panel"><div className="panel-heading"><div><h2>{languageText('principal','Préférences','Preferences')}</h2><p>Paramètres locaux de l’interface</p></div></div><div className="preference-row"><div><b>{t.language}</b><small>Français / English</small></div><select defaultValue="fr"><option value="fr">Français</option><option value="en">English</option></select></div><div className="preference-row"><div><b>{t.theme}</b><small>Selon votre préférence</small></div><select><option>Clair</option><option>Sombre</option><option>Système</option></select></div><div className="preference-row"><div><b>Fuseau horaire</b><small>Heure locale de l’établissement</small></div><b>Africa/Douala</b></div><div className="preference-row"><div><b>Format des dates</b><small>Jour / mois / année</small></div><b>jj/mm/aaaa</b></div></section></div> }

function EnrollmentDialog({t,step,setStep,provisional,setProvisional,onClose,notify}:{t:Copy;step:number;setStep:(value:number)=>void;provisional:boolean;setProvisional:(value:boolean)=>void;onClose:()=>void;notify:(message:string)=>void}) { const stepLabels=[t.stepIdentity,t.stepContacts,t.stepSchool,t.stepDocuments]; return <div className="dialog-backdrop"><section className="form-dialog enrollment-dialog" role="dialog" aria-modal="true" aria-labelledby="enroll-title"><div className="dialog-heading"><div><h2 id="enroll-title">{t.newEnrollment}</h2><p>{t.draft}</p></div><button className="icon-button" aria-label="Fermer" onClick={onClose}><X size={19}/></button></div><FormStepper steps={stepLabels} current={step}/><div className="enrollment-fields">{step===0?<><label>{t.firstName}<input required placeholder="Ex. Arielle"/></label><label>{t.lastName}<input required placeholder="Ex. Mbarga"/></label><label>{t.birthDate}<input type="date"/></label><label>Sexe<select><option>Féminin</option><option>Masculin</option></select></label></>:step===1?<><label>{t.guardian}<input required placeholder="Nom du parent ou tuteur"/></label><label>{languageText('secretary','Téléphone du tuteur','Guardian phone')}<input type="tel" required placeholder="+237 6…"/></label><label>{languageText('secretary','E-mail du tuteur','Guardian email')}<input type="email" placeholder="nom@exemple.cm"/></label><label>{languageText('secretary','Contact d’urgence','Emergency contact')}<input type="tel" placeholder="+237 6…"/></label></>:step===2?<><label>{t.classLabel}<select>{classes.map(c=><option key={c.name}>{c.name}</option>)}</select></label><label>{t.previousSchool}<input placeholder="Établissement précédent"/></label><label>{t.stream}<select><option>Général</option><option>Électrotechnique</option><option>Comptabilité</option></select></label></>:<><fieldset className="document-checks"><legend>{t.requiredDocuments}</legend>{['Acte de naissance','Bulletins de l’année précédente','Photo 4×4','Certificat de scolarité'].map((doc)=><label key={doc}><input type="checkbox"/>{doc}</label>)}</fieldset><label className="checkbox-label"><input type="checkbox" checked={provisional} onChange={(e)=>setProvisional(e.target.checked)}/>{t.provisionalEnrollment}</label><div className="matricule-preview"><LockKeyhole size={15}/>{t.matricule} · généré à la validation du dossier</div></>}</div><div className="dialog-actions"><button className="button-secondary" onClick={()=>step===0?onClose():setStep(step-1)}>{step===0?t.cancel:t.back}</button>{step<3?<button className="button-primary" onClick={()=>setStep(step+1)}>{t.continue}<ArrowRight size={15}/></button>:<button className="button-primary" onClick={()=>{notify(t.enrollmentCreated);onClose()}}><Check size={15}/>{t.finishEnrollment}</button>}</div></section></div> }
function AnnouncementDialog({t,onClose,notify}:{t:Copy;onClose:()=>void;notify:(message:string)=>void}) { return <div className="dialog-backdrop"><section className="form-dialog" role="dialog" aria-modal="true" aria-labelledby="announce-title"><div className="dialog-heading"><div><h2 id="announce-title">{t.publishAnnouncement}</h2><p>{t.audience} · {t.allClasses}</p></div><button className="icon-button" onClick={onClose} aria-label="Fermer"><X size={19}/></button></div><form className="inline-form" onSubmit={(e)=>{e.preventDefault();notify(t.announcementPublished);onClose()}}><label>{t.announcementTitle}<input required placeholder="Titre de l’annonce"/></label><label>{t.audience}<select><option>{t.allClasses}</option><option>Premier cycle</option><option>Second cycle</option>{classes.map(c=><option key={c.name}>{c.name}</option>)}</select></label><label>{t.message}<textarea required rows={4} placeholder="Votre annonce…"/></label><label className="checkbox-label"><input type="checkbox"/>{t.urgent}</label><div className="dialog-actions"><button className="button-secondary" type="button" onClick={onClose}>{t.cancel}</button><button className="button-primary" type="submit"><Send size={15}/>{t.publish}</button></div></form></section></div> }
